INSERT INTO artistas (clave, nombre, biografia, paleta) VALUES
  ('wildfire', 'Wildfire Games', 'Estudio de voluntarios detrás de 0 A.D., un juego libre de estrategia histórica. Su banda sonora, encabezada por el compositor Omri Lahav, mezcla orquesta con instrumentos de todo el mundo antiguo.', 'terra'),
  ('westlund', 'Mattias Westlund', 'Compositor de varios de los temas más queridos de The Battle for Wesnoth, entre ellos Breaking the Chains y Return to Wesnoth.', 'fable'),
  ('kaufman', 'Doug Kaufman', 'Compositor de música orquestal para The Battle for Wesnoth.', 'fable'),
  ('pinkham', 'Timothy Pinkham', 'Compositor de música orquestal para The Battle for Wesnoth.', 'fable'),
  ('reilly', 'Ryan Reilly', 'Compositor de música orquestal para The Battle for Wesnoth.', 'fable'),
  ('nicoll', 'Jeremy Nicoll', 'Compositor de música orquestal y coral para The Battle for Wesnoth.', 'fable'),
  ('buckley', 'Scott Buckley', 'Compositor de música orquestal y cinematográfica que comparte buena parte de su obra con licencias Creative Commons.', 'fable'),
  ('kpone', 'K-Pone', 'Martin Strohmeier, conocido como K-Pone, compuso la música de OpenClonk, un juego libre de acción y construcción. Pasa del house al reggae y del rock al ambient.', 'tropic'),
  ('wkfo', 'WKFO', 'Arda Güler, conocido como WKFO, aportó música electrónica al simulador espacial libre Pioneer, incluida una fuga de Bach en clave techno.', 'cosmos'),
  ('s20dan', 's20dan', 'Músico de la comunidad de Pioneer. Firma Space Groove con Redders y un arreglo de Marte, de Gustav Holst.', 'cosmos'),
  ('pioneer', 'Pioneer Space Sim', 'Pioneer es un simulador espacial libre hecho por voluntarios. Su música acompaña los viajes entre estrellas.', 'cosmos');
INSERT INTO albumes (clave, titulo, artista_id, anio, descripcion, sitio_web, credito, paleta, motivo) VALUES
  ('0ad', '0 A.D. (Banda sonora)', (SELECT id FROM artistas WHERE clave = 'wildfire'), NULL, 'Música de 0 A.D., un juego libre de estrategia histórica, compuesta por Omri Lahav y otros músicos. Viaja por Grecia, Roma, Egipto, la India y los pueblos celtas.', 'https://play0ad.com', 'Wildfire Games (wildfiregames.com)', 'terra', 'arches'),
  ('wesnoth', 'The Battle for Wesnoth OST', NULL, NULL, 'Banda sonora orquestal de The Battle for Wesnoth, un juego libre de fantasía por turnos.', 'https://www.wesnoth.org', 'Compositores de The Battle for Wesnoth (wesnoth.org)', 'fable', 'peaks'),
  ('openclonk', 'OpenClonk', (SELECT id FROM artistas WHERE clave = 'kpone'), '2014–2016', 'House, reggae, rock y ambient compuestos por Martin Strohmeier (K-Pone) para el juego libre OpenClonk.', 'https://www.openclonk.org', 'Martin Strohmeier (K-Pone), OpenClonk (openclonk.org)', 'tropic', 'sun'),
  ('pioneer', 'Pioneer', NULL, NULL, 'Electrónica espacial y clásicos reinventados del simulador libre Pioneer.', 'https://pioneerspacesim.net', 'Colaboradores de Pioneer Space Sim (pioneerspacesim.net)', 'cosmos', 'orbit');
