  ('sol', NULL, 'Sol y playa', 'Ritmos tropicales y luminosos para arrancar el día.', '["#FF7A45", "#FFD166", "#06A3A3", "#FFE8C2"]', 'sun'),
  ('enfoque', NULL, 'Enfoque total', 'Instrumental tranquilo para estudiar, trabajar o leer sin distracciones.', '["#0F2A3D", "#1E6F8C", "#9AD1D4", "#F2E8CF"]', 'rings'),
  ('epica', NULL, 'Épica total', 'Orquestas, tambores y coros para sentir que conquistas el mundo.', '["#2A0A0A", "#B3261E", "#F2A541", "#FFE6A7"]', 'peaks'),
  ('mundo', NULL, 'Vuelta al mundo', 'Del Nilo a Japón, pasando por el Mediterráneo y la India.', '["#0B3C49", "#E07A5F", "#F2CC8F", "#81B29A"]', 'arches'),
  ('celta', NULL, 'Taberna celta', 'Gaitas, arpas y violines para una noche de cuentos.', '["#0F2E1D", "#2F9E44", "#F4D35E", "#C9E4CA"]', 'waves'),
  ('electro', NULL, 'Pulso electrónico', 'Beats, sintetizadores y algo de rock para subir la energía.', '["#14002B", "#FF2E88", "#2EE6D6", "#FCEE0A"]', 'stripes'),
  ('noche', NULL, 'Noche tranquila', 'Para bajar el ritmo y quedarse dormido.', '["#0B0A23", "#2B2370", "#8C7AE6", "#F5E9C8"]', 'peaks'),
  ('aventura', NULL, 'Aventura fantástica', 'La banda sonora de un viaje por reinos lejanos.', '["#102A43", "#3E7CB1", "#F0B429", "#D9E2EC"]', 'rings'),
  ('clasicos', NULL, 'Clásicos reinventados', 'Bach y Holst entre la orquesta y el sintetizador.', '["#1E1A16", "#8C6A3F", "#E9D8A6", "#C1121F"]', 'grid');
